--- Players.LocalPlayer.PlayerScripts.Player.DisableFootsteps [LocalScript]
-- y u r i

local function watchCharacter(arg1)
	local tbl1 = {}
	local function muteFootsteps(arg1)
		if not arg1:IsA("Sound") or arg1.Name ~= "Running" then
			return
		end

		arg1.Volume = 0
		local function fn2()
			if arg1.Volume ~= 0 then
				arg1.Volume = 0
			end
		end

		table.insert(tbl1, arg1:GetPropertyChangedSignal("Volume"):Connect(fn2))
	end

	local var1 = muteFootsteps
	table.insert(tbl1, arg1.DescendantAdded:Connect(var1))
	for k1, v1 in ipairs(arg1:GetDescendants()) do
		muteFootsteps(v1)
	end

	arg1.Destroying:Once(function()
		for k1, v1 in ipairs(tbl1) do
			v1:Disconnect()
		end
	end)
