function birthdayBoostActive()
	return 0 < (birthdayBoostRemaining or 0)
end

function addBirthdayBoostTime()
	local var1 = (birthdayBoostRemaining or 0) + BIRTHDAY_BOOST_SECONDS
	birthdayBoostRemaining = var1
	var1 = (partyDefenseBoostRemaining or 0) + BIRTHDAY_BOOST_SECONDS
	partyDefenseBoostRemaining = var1
	var1 = (partySpeedBoostRemaining or 0) + BIRTHDAY_BOOST_SECONDS
	partySpeedBoostRemaining = var1
	partyDamageBoost = 2
	refreshSideBoostIcons()
	setPartySideBoostVisible("Speed", true)
end

function updateBirthdayBoost(arg1)
	local var1 = birthdayBoostActive()
	local var2 = math.max(0, (birthdayBoostRemaining or 0) - arg1)
	birthdayBoostRemaining = var2
	local var3 = 0 < (partyDefenseBoostRemaining or 0)
	var2 = math.max(0, (partyDefenseBoostRemaining or 0) - arg1)
	partyDefenseBoostRemaining = var2
	local var4 = 0 < (partySpeedBoostRemaining or 0)
	var2 = math.max(0, (partySpeedBoostRemaining or 0) - arg1)
	partySpeedBoostRemaining = var2
	if var1 and (not birthdayBoostActive()) then
		partyDamageBoost = 1
	end

	if var3 == (0 < (partyDefenseBoostRemaining or 0)) then
		if var1 == birthdayBoostActive() then
			if var4 == (0 < (partySpeedBoostRemaining or 0)) then
				return
			end
		end
	end

	refreshSideBoostIcons()
end

function sideBoostActive(arg1)
	if arg1 == "Attack" then
		return birthdayBoostActive()
	end

	if arg1 == "Defense" then
		return 0 < (partyDefenseBoostRemaining or 0)
	end

	if arg1 == "Speed" then
		return 0 < (partySpeedBoostRemaining or 0)
	end

	return false
end

function refreshSideBoostIcons()
	local str1 = "Attack"
	setPartySideBoostVisible("Attack", sideBoostActive(str1))
	str1 = "Defense"
	setPartySideBoostVisible("Defense", sideBoostActive(str1))
	str1 = "Speed"
	setPartySideBoostVisible("Speed", sideBoostActive(str1))
end

function startHeadstartBoosts()
	if var1:GetAttribute("HeadstartStrengthEquipped") == true then
		birthdayBoostRemaining = 15
		partyDamageBoost = 2
	end

	if var1:GetAttribute("HeadstartDefenseEquipped") == true then
		partyDefenseBoostRemaining = 15
	end

	if require(game.ReplicatedStorage.FnafWorldChips).IsEquipped(var1, "SpeedChip") then
		partySpeedBoostRemaining = 15
	end

	refreshSideBoostIcons()
end

