	dialogues = {
		Intro = {
			pages = {
				{
					text = "I know you may feel like going out and taking a stroll, but something seems very wrong today.",
					key = "Intro_1",
				},
				{
					text = "All is NOT well in Animatronica. Animatronic Village? Village-tronica? (We are working on it.) The point is that something is horribly wrong!",
					key = "Intro_2",
				},
				{
					text = "There have been a lot of bizarre creatures roaming around lately, even some that look like... *gulp*  ...us.",
					key = "Intro_3",
				},
				{
					text = "We aren't prepared to deal with situations like this. Something bad must have happened on the flipside.",
					key = "Intro_4",
				},
				{
					text = "Go see what you can find. Be careful though, our wood-cutting Auto-Chipper has gone haywire! It has been jumpscaring me all day!",
					key = "Intro_5",
				},
			},
			glitchPages = {
				{ text = "But you don't really believe that do you?", key = "Intro_6" },
				{
					text = "There is a task for you to complete. You have to leave breadcrumbs for him, to help him find his way.",
					key = "Intro_7",
				},
			},
			background = "rbxassetid://102949725682933",
		},
		ChoppysWoodsClue = {
			pages = {
				{
					text = "I think I found a clue as to what is happening! Look behind me, there is a tree that is distorted and glitched.",
					key = "ChoppysWoodsClue_1",
				},
				{
					text = "You don't know as much as I do, but I will tell you that this is a safe haven, a sanctuary. Whatever has gone wrong, we have to fix it. It will be an adventure!",
					key = "ChoppysWoodsClue_2",
				},
				{
					text = "Something horrible must have happened on the flipside, because it's causing this world to fracture. Objects like the tree behind me have broken.",
					key = "ChoppysWoodsClue_3",
				},
				{
					text = "But I think you can use these fractures to get to places you couldn't reach before. You have to go and find the source of these fractures!",
					key = "ChoppysWoodsClue_4",
				},
			},
			glitchPages = {
				{ text = "Yes, the world beneath the surface world.", key = "ChoppysWoodsClue_5" },
				{
					text = "This is a safe place- a sanctuary. The truth is that there is no safe place. You don't understand that; you were made for one thing.",
					key = "ChoppysWoodsClue_6",
				},
				{
					text = "There is a task for you to complete. Before you follow this passage, go back. Find the clock.",
					key = "ChoppysWoodsClue_7",
				},
			},
			background = "rbxassetid://118813152288580",
		},
		ChoppysWoods2 = {
			pages = {
				{
					text = "Great! Be sure to press that button behind you to clear the path for later. That way you won't have to take the long way again!",
					key = "ChoppysWoods2_1",
				},
				{
					text = "I think that a lot of these 'monsters' are misguided side-effects of whatever has happened on the flipside.",
					key = "ChoppysWoods2_2",
				},
				{
					text = "It looks like you can knock some sense into them and then they'll join you. How wonderfully convenient!",
					key = "ChoppysWoods2_3",
				},
				{
					text = "You need to find another sub-tunnel under the game, and it's probably hidden inside another glitched object!",
					key = "ChoppysWoods2_4",
				},
				{
					text = "Ahead are the Dusting Fields, you will probably find the next glitched object there. Be careful; things only get more dangerous from here!",
					key = "ChoppysWoods2_5",
				},
			},
			glitchPages = {
				{
					text = "Things don't get more dangerous. You are being played.",
					key = "ChoppysWoods2_6",
				},
				{
					text = "You are being led through hoops. Meanwhile the puppet-master is laughing at you.",
					key = "ChoppysWoods2_7",
				},
				{
					text = "You do need to find the Dusting Fields, but not because there is any urgent adventure ahead. Find the clock.",
					key = "ChoppysWoods2_8",
				},
			},
			background = "rbxassetid://118813152288580",
		},
		DustingFields = {
			pages = {
				{
					text = "The sub-tunnel must be up ahead. However, it looks like something is blocking the path. I'm sure it's nothing you can't handle!",
					key = "DustingFields_1",
				},
				{
					text = "I do need to warn you of something, though. When you enter a glitched object into a sub-tunnel, it's possible to find yet another glitched object inside.",
					key = "DustingFields_2",
				},
				{
					text = "That will take you into a subtunnel beneath the subtunnel! There may even be more glitched objects there!",
					key = "DustingFields_3",
				},
				{
					text = "Just be sure to never go more than three glitches down! I'm not sure if you would find your way back up!",
					key = "DustingFields_4",
				},
				{
					text = "Be sure to always search for new Chips and Bytes; they will be a huge help against monsters like the one up ahead!",
					key = "DustingFields_5",
				},
			},
			glitchPages = {
				{
					text = "Play along for now. You are being pulled on a string for his amusement.",
					key = "DustingFields_6",
				},
				{
					text = "Don't enter the glitch yet; you need to go into the mine. Find the clock.",
					key = "DustingFields_7",
				},
			},
			background = "rbxassetid://91357201908165",
		},
		LilygearLake = {
			pages = {
				{
					text = "You've reached Lilygear Lake! From here I don't know where your adventure will take you!",
					key = "LilygearLake_1",
				},
				{
					text = "You should be keeping your eyes open for another glitched object. They are the only way to get to places that are otherwise unreachable!",
					key = "LilygearLake_2",
				},
				{
					text = "Be careful in the waters of Lilygear Lake! I hear there is a seamonster that attacks at random! Be ready to fight! Good luck!",
					key = "LilygearLake_3",
				},
			},
			glitchPages = {
				{ text = "Yes, well, everything attacks at random. Doesn't it?", key = "LilygearLake_4" },
				{
					text = "The one who pulls the strings is always watching. He allows you to progress.",
					key = "LilygearLake_5",
				},
				{
					text = "Follow the trail that they have created for you; play along. There is another mine that you must find before you enter the glitched object.",
					key = "LilygearLake_6",
				},
				{ text = "Find the clock.", key = "LilygearLake_7" },
			},
			background = "rbxassetid://118813152288580",
		},
		BlacktombYard = {
			pages = {
				{
					text = "This is a horribly spooky place. I think I'll stay right here.",
					key = "BlacktombYard_1",
				},
				{
					text = "You, however, need to keep going! This is a graveyard for broken and unwanted creations. It's full of nastiness and traps.",
					key = "BlacktombYard_2",
				},
				{
					text = "I don't think everything here is as it seems. Check the graves and the trees. This whole place is full of illusion!",
					key = "BlacktombYard_3",
				},
			},
			glitchPages = {
				{ text = "One thing is true. Nothing here is as it seems.", key = "BlacktombYard_4" },
				{
					text = "You need to find another clock, but the passage will not be easy. There is a secret sub-corridor that leads to Pinwheel Circus under this graveyard.",
					key = "BlacktombYard_5",
				},
				{ text = "Find the clock. Everything else is a deception.", key = "BlacktombYard_6" },
			},
			background = "rbxassetid://138811473613876",
		},
	},
